print(f"Vertices: {len(vertices)}, Edges: {len(edges)}")

def compute_diffs(labels):
    """labels is dict from (g,i) to value"""
    diffs = {}
    for (u, v) in edges:
        d = abs(labels[u] - labels[v])
        diffs[(u,v)] = d
    return diffs

def count_conflicts(diffs):
    from collections import Counter
    c = Counter(diffs.values())
    conflicts = sum(v-1 for v in c.values() if v > 1)
    return conflicts

def local_search(max_iter=1000000):
    # Start with random assignment
    available = list(range(37))
    random.shuffle(available)
    labels = {}
    idx = 0
    for g in range(4):
        for i in range(4):
            labels[(g,i)] = available[idx]
            idx += 1

    best_conflicts = count_conflicts(compute_diffs(labels))
    best_labels = dict(labels)

    start = time.time()
    for iteration in range(max_iter):
        if best_conflicts == 0:
            break

        # Try a random swap
        u, v = random.sample(vertices, 2)
        # Swap
        labels[u], labels[v] = labels[v], labels[u]
        new_conflicts = count_conflicts(compute_diffs(labels))

        if new_conflicts <= best_conflicts:
            best_conflicts = new_conflicts
            best_labels = dict(labels)
            if new_conflicts < best_conflicts:
                pass  # accept
        else:
            # Revert
            labels[u], labels[v] = labels[v], labels[u]

        if iteration % 100000 == 0:
            elapsed = time.time() - start
            print(f"Iter {iteration}, conflicts: {best_conflicts}, time: {elapsed:.1f}s")

    return best_labels, best_conflicts

