def simulated_annealing(max_iter=2000000, temp_start=100.0, temp_end=0.01):
    # Start with random assignment
    available = list(range(37))
    random.shuffle(available)
    labels = {}
    idx = 0
    for g in range(4):
        for i in range(4):
            labels[(g,i)] = available[idx]
            idx += 1

    diffs = compute_diffs(labels)
    current_conflicts = count_conflicts(diffs)

    best_conflicts = current_conflicts
    best_labels = dict(labels)

    start = time.time()
    for iteration in range(max_iter):
        if best_conflicts == 0:
            break

        temp = temp_start * (temp_end / temp_start) ** (iteration / max_iter)

        # Try a random swap
        u, v = random.sample(vertices, 2)
        old_u, old_v = labels[u], labels[v]

        # Compute delta efficiently
        # Only edges incident to u or v change
        delta = 0
        # Temporarily swap
        labels[u], labels[v] = old_v, old_u

        # Check all edges incident to u or v
        changed_edges = set()
        for (a, b) in edges:
            if a == u or b == u or a == v or b == v:
                changed_edges.add((a,b))

        # Recompute conflicts for changed edges
        # This is a bit expensive but let's do it
        new_diffs = compute_diffs(labels)
        new_conflicts = count_conflicts(new_diffs)

        accept = False
        if new_conflicts <= current_conflicts:
            accept = True
        else:
            prob = math.exp(-(new_conflicts - current_conflicts) / temp)
            if random.random() < prob:
                accept = True

        if accept:
