            diffs = new_diffs
            if current_conflicts < best_conflicts:
                best_conflicts = current_conflicts
                best_labels = dict(labels)
        else:
            labels[u], labels[v] = old_u, old_v

        if iteration % 200000 == 0:
            elapsed = time.time() - start
            print(f"Iter {iteration}, best: {best_conflicts}, current: {current_conflicts}, temp: {temp:.4f}, time: {elapsed:.1f}s")

    return best_labels, best_conflicts

